function paint(rows: string[], pal: Record<string, string>): HTMLCanvasElement {
  const w = Math.max(...rows.map(r => r.length));
  const p = new PixelCanvas(w, rows.length);
  rows.forEach((r, y) => [...r].forEach((ch, x) => ch !== '.' && pal[ch] && p.px(x, y, pal[ch])));
  return p.outline('auto', 0.22).toCanvas();
}

/** HD idle frames of an NPC (or of a wanderer: the grey postman, the grey lantern). */
export function npcFrames(id: NpcId | 'postman' | 'lantern'): HTMLCanvasElement[] {
  if (id === 'aldric') return ALDRIC.map(f => paint(f, ALDRIC_PAL));
  const p = PEOPLE[id];
  return p.frames.map(f => paint(f, p.pal));
}

/** Wren's frames as she walks with the heroes: a walk, standing, a shot (nock, draw, loose), and down on one knee. */
export function wrenFrames(): Record<'walk' | 'idle' | 'shoot' | 'kneel', HTMLCanvasElement[]> {
  const f = (k: keyof typeof WREN) => WREN[k].map(rows => paint(rows, WREN_PAL));
  return { walk: f('walk'), idle: f('idle'), shoot: f('shoot'), kneel: f('kneel') };
}

